def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    rich_threat = 0.0
    urgent_opp = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('budget', 0) > rich_threat:
            rich_threat = float(opp.get('budget', 0))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - supply) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = 20.0 + 10.0 * scarcity

    if supply >= 22:
        base -= 6.0
    elif supply <= 17:
        base += 10.0

    if highest_prev >= 120.0:
        base -= 4.0
    elif highest_prev >= 90.0:
        base += 3.0
    else:
        base += 1.5

    if avg_prev >= 80.0:
        base += 2.0

    if rich_threat >= 250.0:
        base -= 2.0

    base += 3.0 * urgent_opp

    if hp <= 2 or no_water >= 2:
        bid = max(base, 92.0 + 8.0 * scarcity)
    elif hp <= 4 or no_water >= 1:
        bid = max(base, 58.0 + 10.0 * scarcity)
    else:
        bid = base

    if day >= 8 and hp > 4 and no_water == 0:
        bid -= 4.0

    if budget < 60:
        bid = min(bid, budget)
    elif budget < 120:
        bid = min(bid, 0.72 * budget)
    else:
        bid = min(bid, 0.38 * budget + 8.0)

    floor_bid = 8.0 if hp > 4 and no_water == 0 else 18.0
    bid = max(floor_bid, bid)
    bid = min(budget, bid)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Pressure estimate: if someone was bidding near/above salary, competition is intense.
    intense = highest_prev_bid >= DAILY_SALARY * 0.85

    # Supply tightness: if supply is close to requirement, water is more scarce.
    scarcity = 1.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # Decide aggressiveness.
    # If my hp is low or I'm already accumulating no-water days, bid more.
    urgency = 0.0
    if my_hp <= 2.0:
        urgency = 1.0
    elif my_hp <= 4.0:
        urgency = 0.7
    elif my_no_water_days >= 2:
        urgency = 0.6
    else:
        urgency = 0.2

    # Base bid: conservative unless urgency+scarcity+intense.
    # Target is to secure water without matching the highest bidder when unnecessary.
    if intense:
        target = DAILY_SALARY * (0.35 + 0.25 * scarcity + 0.35 * urgency)
        # If urgency is high, near-match the leader; else undercut.
        if urgency >= 0.8:
            target = max(target, min(my_budget, highest_prev_bid * 0.95))
        else:
            target = min(target, highest_prev_bid * 0.6 + DAILY_SALARY * 0.2)
    else:
        target = DAILY_SALARY * (0.25 + 0.35 * scarcity + 0.4 * urgency)

    # Ensure we don't bid more than budget and keep non-negative.
    bid = max(0.0, min(my_budget, target))

    # If supply is extremely low and we are not in danger, still bid enough to avoid falling behind.
    if supply <= float(WATER_REQ) + 0.5 and my_hp > 4.0 and my_no_water_days == 0:
        bid = min(my_budget, max(bid, DAILY_SALARY * 0.45))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(yesterday_bids)

    # If supply is tight, bid aggressively to ensure survival
    if supply < 18:
        return min(my_status['budget'], max(max_prev + 2.0, DAILY_SALARY * 0.85))

    # If supply is high, bid conservatively
    if supply > 22:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Default behavior: slightly exceed previous max to secure water
    return min(my_status['budget'], max(max_prev * 1.05, DAILY_SALARY * 0.55))
